(--ug-bg)}.ug-ui [data-ug-sort]{font:inherit;border:0;background:transparent;color:inherit;cursor:pointer;text-align:start;padding:2px}.ug-ui [aria-sort=ascending] [data-ug-sort]:after{content:" ↑"}.ug-ui [aria-sort=descending] [data-ug-sort]:after{content:" ↓"}.ug-ui .ug-table-pagination{display:flex;align-items:center;gap:12px;justify-content:space-between;flex-wrap:wrap;margin-top:16px}.ug-ui [data-ug-table-status],.ug-ui [data-ug-writing-status]{color:var(--ug-muted);font-size:.85em}.ug-ui [data-ug-writing-input][aria-invalid=true]{border-color:var(--ug-danger)}
